import sys

def solve():
    s = sys.stdin.readline().strip()
    line2 = sys.stdin.readline().strip()
    if not line2:
        return
    k = int(line2)

    n = len(s)
    total_len = n + k

    max_l = 0

    # Try every possible starting position i in the new string (0 to total_len-1)
    # Try every possible half-length h such that the tandem repeat fits
    for i in range(total_len):
        # The tandem repeat has length 2*h, so it occupies indices [i, i + 2*h - 1]
        # We need i + 2*h <= total_len => 2*h <= total_len - i => h <= (total_len - i) // 2
        max_h_for_i = (total_len - i) // 2

        for h in range(1, max_h_for_i + 1):
            # Check if a tandem repeat of length 2*h starting at i is possible
            # The repeat consists of two halves: first half from i to i+h-1, second from i+h to i+2h-1
            possible = True
            for j in range(h):
                idx1 = i + j
                idx2 = i + h + j

                # If the second character is beyond the original string s, we can choose it freely
                if idx2 >= n:
                    continue
                # If both are within the original string, they must match
                if idx1 >= n or idx2 >= n:
                    if idx1 >= n:
                        possible = False
                        break
                    # idx2 >= n handled above, so here idx1 < n and idx2 >= n, which is fine (free choice)
                else:
                    if s[idx1] != s[idx2]:
                        possible = False
                        break

            if possible:
                if 2 * h > max_l:
                    max_l = 2 * h

    print(max_l)

if __name__ == "__main__":
    solve()
